import json
DEFAULT_COLUMNS = {'timestamp': 'sampled_at', 'value': 'watt_hours', 'meter': 'meter_id'}
def resolve_columns(env, args):
    columns = dict(DEFAULT_COLUMNS)
    columns.update(json.loads(env.get('METER_COLUMNS', '{}')))
    if args.value_column is not None:
        columns['value'] = args.value_column
    return columns

